/* a curve of computed points: f(t) for t in [t0,t1], mapped to x in [x0,x1] and y = yc - k*f */
const CM_pts=(f,t0,t1,x0,x1,yc,k,n)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return p};
const CM_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160,ex='')=>`<polyline points="${CM_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const CM_area=(f,t0,t1,x0,x1,yc,k,col,op=.25,n=120,ex='')=>`<polygon points="${x0},${yc} ${CM_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')} ${x1},${yc}" fill="${col}" fill-opacity="${op}" stroke="${col}" stroke-width="3" stroke-linejoin="round" ${ex}/>`;
