const CM_pre=f=>20*Math.log10(Math.sqrt(1+(f/CM_f1)**2));        /* gain in dB */
/* noise power densities over 0..W (u = f/W, W = 15 kHz, x = W/f1 = 7.069) */
const CM_X=15000/CM_f1;
const CM_nPlain=u=>u*u;                                           /* discriminator noise, f² */
