function EXTRA(R,ICON){
 /* hook: the programme is strongest low, the discriminator noise grows as f² */
 ICON.cmHiss=(x,y)=>{const X0=20,X1=380,YB=210;return `<g transform="translate(${x-200} ${y-150})">${CM_box(0,0,400,300,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${CM_L(X0,YB,X1+4,YB,CM_GRY,2)}${CM_area(CM_msg,0,1,X0,X1,YB,150,BLU,.22)}${CM_curve(CM_nPlain,0,1,X0,X1,YB,150,ORG,5)}
  ${CM_T(40,60,'music',{fs:24,fw:800,fill:BLU})}${CM_T(372,52,'hiss',{fs:26,fw:800,a:'end',fill:ORG})}
  ${CM_T(X0,240,'bass',{fs:22,fill:CM_MUT})}${CM_T(X1,240,'treble',{fs:22,a:'end',fill:CM_MUT})}
  ${CM_T(200,280,'after the FM discriminator',{fs:22,a:'middle',fill:CM_MUT})}</g>`};
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.cmEmph=(x,y)=>{const xf=f=>20+380*(Math.log10(f)-2)/Math.log10(200),yd=d=>165-d*6;return `<g transform="translate(${x-210} ${y-165})">
  ${CM_L(20,165,404,165,CM_GRY,2)}${CM_curve(f=>CM_pre(10**f),2,Math.log10(20000),20,400,165,6,BLU,5)}${CM_curve(f=>-CM_pre(10**f),2,Math.log10(20000),20,400,165,6,GRN,5)}${CM_L(20,165,400,165,ORG,3,'stroke-dasharray="9 7"')}
  ${CM_T(24,40,'pre: +17 dB at 15 kHz',{fs:24,fw:800,fill:BLU})}${CM_T(24,300,'de: the mirror',{fs:24,fw:800,fill:GRN})}${CM_T(400,154,'product 0 dB',{fs:22,fw:800,a:'end',fill:ORG})}</g>`};
 ICON.cmStereo=(x,y)=>{const xf=f=>20+f*7;return `<g transform="translate(${x-210} ${y-165})">
  ${CM_L(10,250,420,250,CM_GRY,2)}<rect x="${xf(0)}" y="90" width="${xf(15)-xf(0)}" height="160" fill="${BLU}" fill-opacity=".2" stroke="${BLU}" stroke-width="3"/>
  ${CM_T(xf(7.5),180,'L + R',{fs:24,fw:800,a:'middle',fill:BLU})}${CM_L(xf(19),250,xf(19),170,ORG,6)}${CM_T(xf(19),158,'19',{fs:24,fw:800,a:'middle',fill:ORG})}
  <rect x="${xf(23)}" y="190" width="${xf(53)-xf(23)}" height="60" fill="${GRN}" fill-opacity=".2" stroke="${GRN}" stroke-width="3"/>${CM_L(xf(38),250,xf(38),120,GRN,3,'stroke-dasharray="7 6"')}
  ${CM_T(xf(30.5),230,'L − R',{fs:24,fw:800,a:'middle',fill:GRN})}${CM_T(xf(38),108,'38: off',{fs:22,fw:800,a:'middle',fill:GRN})}
  ${[0,15,23,53].map(f=>CM_T(xf(f),282,String(f),{fs:22,a:'middle',fill:CM_MUT})).join('')}${CM_T(410,316,'kHz',{fs:22,a:'end',fill:CM_MUT})}</g>`};
 ICON.cmChain=(x,y)=>{const A=[['RF',BLU],['mixer',BLU],['IF 10.7',ORG]],B=[['limiter',ORG],['discr.',ORG],['decoder',GRN]];return `<g transform="translate(${x-210} ${y-165})">
  ${A.map(([t,col],i)=>CM_blk(i*145,40,120,64,t,col)+(i<2?CM_arrow(i*145+122,72,i*145+143,72,INK,3):'')).join('')}${CM_arrow(350,106,350,146,INK,3)}
  ${B.map(([t,col],i)=>CM_blk(290-i*145,148,120,64,t,col)+(i<2?CM_arrow(290-i*145-2,180,290-i*145-23,180,INK,3):'')).join('')}${CM_arrow(60,214,60,254,INK,3)}
  ${CM_blk(0,256,420,60,'de-emphasis, then L and R',GRN,{fill:'#E3FAF1'})}</g>`};
}
